   504  static void *parse_key_value(struct parser *parser)
   505  {
   506      struct config_line line = {.type = CONFIG_LINE_TYPE_LINE};
   507      struct lexeme *lexeme;
   508      size_t key_size;
   509
   510      while (lexeme_buffer_consume(&parser->buffer, &lexeme)) {
   511          lwan_strbuf_append_str(&parser->strbuf, lexeme->value.value,
   512                                 lexeme->value.len);
   513
   514          if (!lexeme_ring_buffer_empty(&parser->buffer))
   515              lwan_strbuf_append_char(&parser->strbuf, '_');
   516      }
   517      key_size = lwan_strbuf_get_length(&parser->strbuf);
   518      lwan_strbuf_append_char(&parser->strbuf, '\0');
   519
   520      while (lex_next(&parser->lexer, &lexeme)) {
   521          switch (lexeme->type) {
   522          case LEXEME_VARIABLE_DEFAULT:
   523          case LEXEME_VARIABLE: {
   524              const char *value;
   525
   526              value = secure_getenv_len(lexeme->value.value, lexeme->value.len);
   527              if (lexeme->type == LEXEME_VARIABLE) {
   528                  if (!value) {
   529                      lwan_status_error(
   530                          "Variable '$%.*s' not defined in environment",
   531                          (int)lexeme->value.len, lexeme->value.value);
   532                      return NULL;
   533                  } else {
   534                      lwan_strbuf_append_strz(&parser->strbuf, value);
   535                  }
   536              } else {
   537                  struct lexeme *var_name = lexeme;
   538
   539                  if (!lex_next(&parser->lexer, &lexeme)) {
   540                      lwan_status_error(
   541                          "Default value for variable '$%.*s' not given",
   542                          (int)var_name->value.len, var_name->value.value);
   543                      return NULL;
   544                  }
   545
   546                  if (lexeme->type != LEXEME_STRING) {
   547                      lwan_status_error("Wrong format for default value");
   548                      return NULL;
   549                  }
   550
   551                  if (!value) {
   552                      lwan_status_debug(
   553                          "Using default value of '%.*s' for variable '${%.*s}'",
   554                          (int)lexeme->value.len, lexeme->value.value,
   555                          (int)var_name->value.len, var_name->value.value);
   556                      lwan_strbuf_append_str(&parser->strbuf, lexeme->value.value,
   557                                             lexeme->value.len);
   558                  } else {
   559                      lwan_strbuf_append_strz(&parser->strbuf, value);
   560                  }
